-- Generated by scripts/gen_instructional_room_sql.py
-- Required because Buildings & Rooms XML creates external rooms only.
START TRANSACTION;
SET @coep_session := (SELECT uniqueid FROM sessions WHERE academic_initiative='COEP' AND academic_term='Spr' AND academic_year='2026');
SET @coep_dept := (SELECT uniqueid FROM department WHERE session_id=@coep_session AND dept_code='0101');
-- Abort safely on a wrong/missing session or a session that already has rooms.
SELECT CASE WHEN @coep_session IS NULL THEN 1/0 WHEN @coep_dept IS NULL THEN 1/0 WHEN EXISTS (SELECT 1 FROM room WHERE session_id=@coep_session) THEN 1/0 ELSE 1 END AS preflight;
COMMIT;
SELECT COUNT(*) AS instructional_rooms_created FROM room WHERE session_id=@coep_session;
